package fr.formation.clean.interfaceadapter.controller;
import fr.formation.clean.application.boundary.*;import fr.formation.clean.application.usecase.UseCaseException;import fr.formation.clean.domain.entity.DomainException;import fr.formation.clean.interfaceadapter.gateway.ReservationQuery;import java.time.LocalDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reservations")class ReservationController{private final CreateReservationInputBoundary create;private final CancelReservationInputBoundary cancel;private final ReservationQuery query;ReservationController(CreateReservationInputBoundary create,CancelReservationInputBoundary cancel,ReservationQuery query){this.create=create;this.cancel=cancel;this.query=query;}@PostMapping @ResponseStatus(HttpStatus.CREATED)CreateReservationInputBoundary.Output create(@RequestBody Request r){return create.execute(new CreateReservationInputBoundary.Input(r.roomId(),r.organizerEmail(),r.participants(),r.startsAt(),r.endsAt()));}@GetMapping("/{id}")ReservationQuery.View get(@PathVariable UUID id){return query.find(id);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void cancel(@PathVariable UUID id){cancel.execute(id);}record Request(UUID roomId,String organizerEmail,int participants,LocalDateTime startsAt,LocalDateTime endsAt){}@RestControllerAdvice static class Handler{@ExceptionHandler(DomainException.class)ResponseEntity<Map<String,String>>domain(DomainException e){return ResponseEntity.unprocessableEntity().body(Map.of("message",e.getMessage()));}@ExceptionHandler(UseCaseException.class)ResponseEntity<Map<String,String>>missing(UseCaseException e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));}}}
